    void ProfileMenu(string id,Button button){var m=Menu(button);if(id=="dns"){foreach(string profile in new[]{"comss","xbox"}){string p=profile;Entry(m,p=="comss"?"ComssDNS":"Xbox DNS",()=>{shell.Settings.DnsProfileId=p;shell.Settings.DnsProfileName=p=="comss"?"ComssDNS":"Xbox DNS";Save();shell.SelectDnsProfile(p);Render();});}Entry(m,"DNS Manager",()=>shell.OpenDnsSettings());}else{
